INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000001', 'Ai Thinker ESP-01S ESP8266 WiFi Module', 'ESP-01S-WIFI', 12500, 'Compact WiFi module with ESP8266 chip. Ultra-low power consumption, perfect for IoT projects. Supports IEEE802.11 b/g/n protocols with complete TCP/IP stack. Pre-programmed with AT command firmware for easy Arduino integration.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2F20.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FAi-Thinker-ESP-01S-ESP8266-WiFi-Module-3.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FAi-Thinker-ESP-01S-ESP8266-WiFi-Module-2.jpg&w=1920&q=90"]', 'IoT Module', 7);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000002', 'Ai Thinker ESP-12F ESP8266 Serial WiFi Module', 'ESP-12F-WIFI', 18750, 'Advanced ESP8266 module in SMD22 package with PCB antenna. Features Tensilica L106 32-bit microcontroller with clock speeds up to 160MHz. Includes 9 GPIO ports and supports UART/GPIO/ADC/PWM interfaces. Operating temperature -20°C to 85°C.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2F17-1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FAi-Thinker-ESP-12F-ESP8266-Serial-WiFi-Module-3.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FAi-Thinker-ESP-12F-ESP8266-Serial-WiFi-Module-2.jpg&w=1920&q=90"]', 'IoT Module', 3);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000003', 'Ai Thinker ESP-01F ESP8285 Serial WiFi Module', 'ESP-01F-WIFI', 21500, 'Ultra-compact WiFi module with integrated ESP8285 chip and 1MB flash memory. Highly competitive package size with ultra-low power technology. Ideal for home automation, industrial wireless control, wearable electronics, and wireless positioning systems.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FAi-Thinker-ESP-01F-ESP8285-Serial-WiFi-Module-5.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FAi-Thinker-ESP-01F-ESP8285-Serial-WiFi-Module-1.jpg&w=256&q=75","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FAi-Thinker-ESP-01F-ESP8285-Serial-WiFi-Module-2.jpg&w=1920&q=90"]', 'IoT Module', 0);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000004', 'Ai Thinker ESP32-S WiFi+Bluetooth SoC Module', 'ESP32-S-WIFIBT', 35000, 'Powerful dual-mode WiFi and Bluetooth module with ESP32 chip. Features dual-core processor, 520KB SRAM, and ultra-low power consumption. Supports AP, STA, and AP+STA modes. Perfect for smart home automation, industrial control, mesh networks, and video streaming applications.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2F15.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FAi-Thinker-ESP32-S-WiFiBT-SoC-Module-5.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FAi-Thinker-ESP32-S-WiFiBT-SoC-Module-1-1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FAi-Thinker-ESP32-S-WiFiBT-SoC-Module-2-1.jpg&w=1920&q=90"]', 'IoT Module', 15);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000005', 'Ai Thinker NodeMCU ESP8266 Development Board', 'NODEMCU-ESP8266', 57500, 'Complete ESP8266 development board with USB interface and CH340G driver. Open-source firmware based on Lua scripting. Features WiFi connectivity, GPIO pins, ADC, PWM, and multiple communication protocols. Ready to program with Arduino IDE or Lua. Perfect for rapid IoT prototyping.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2F14.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FIMG_6666.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2F103.jpg&w=1920&q=90"]', 'Development Board', 8);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000006', 'Nordic nRF52840 Dongle Bluetooth 5.4 Module', 'NRF52840-DONGLE', 36000, 'Small low-cost USB dongle supporting Bluetooth 5.4, Bluetooth mesh, Thread, Zigbee, 802.15.4, ANT and 2.4GHz proprietary protocols. Features ARM Cortex-M4 CPU, 1MB flash, 256KB RAM. Perfect for wireless development and nRF Connect Desktop applications.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F07%2F485216.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F07%2F485216-1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F07%2F485216-2.jpg&w=1920&q=90"]', 'Bluetooth Module', 12);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000007', 'NRF52840 Low Power BLE Module Ceramic Antenna', 'NRF52840-BLE-CA', 362500, 'Advanced Bluetooth Low Energy module using Nordic NRF52840 SoC with ARM Cortex-M4 FPU. Features 1MB flash cache, 256KB RAM, NFC, USB, and Quad SPI. Includes ARM Cryptocell-310 for best-in-class security with AES 128-bit encryption suite. Ceramic antenna for reliable connectivity.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2020%2F01%2F672604.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2020%2F01%2F8-1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2020%2F01%2F7-3.jpg&w=1920&q=90"]', 'Bluetooth Module', 6);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000008', 'NRF51822 BLE 4.0 Bluetooth Development Board', 'NRF51822-BLE40', 32500, 'Wireless module based on nRF51822 Multiprotocol Bluetooth 4.0 low energy/2.4GHz RF SoC. Features 32kB RAM, ultra-low power consumption. Ideal for ULP wireless applications. Includes GPIO pins with minimal development. Perfect for wearables and IoT sensors.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2020%2F10%2F815817.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2020%2F09%2FNRF51822-BLE4.0-Bluetooth-2.4G-Wireless-Module-Onboard-Rev3-2.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2020%2F09%2FNRF51822-BLE4.0-Bluetooth-2.4G-Wireless-Module-Onboard-Rev3-6.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2020%2F10%2F144.jpg&w=1920&q=90"]', 'Bluetooth Module', 9);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000009', 'HC-05 Bluetooth Serial Module Master Slave', 'HC-05-BT-SERIAL', 16250, 'Classic Bluetooth serial communication module supporting both master and slave modes. Operating voltage 3.3V-6V, 2.4GHz ISM band operation. Seamless connection with computers, PDAs, and Bluetooth adapters. Perfect for wireless UART communication in robotics and automation projects.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2F617819.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FHC-05-4pin-Bluetooth-ModuleMaster-Slave-with-Button-617819-3.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FHC-05-4pin-Bluetooth-ModuleMaster-Slave-with-Button-617819-2.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2F131.jpg&w=1920&q=90"]', 'Bluetooth Module', 23);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000010', 'NRF24L01+ PA LNA Wireless Transceiver Module', 'NRF24L01-PALNA', 27500, '2.4GHz wireless transceiver with Power Amplifier and Low Noise Amplifier. Extended range up to 1100 meters with antenna. Features 3.3V regulator onboard, auto-acknowledge, and multi-channel operation. Ideal for long-range wireless communication projects.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2016%2F07%2F9.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2016%2F07%2FHT1tGQIFHBaXXagOFbX5.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2016%2F07%2F18826-2.jpg&w=1920&q=90"]', 'RF Module', 18);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000011', 'FS1000A 433MHz RF Transmitter Receiver Module', 'FS1000A-433MHZ', 8750, '433MHz RF wireless transmitter and receiver pair. Operating voltage 3-12V, transmission distance over 500m in open space. Output power 16dBm (40mW), data rate up to 10Kbps. OOK amplitude modulation. Perfect for remote control and wireless data transmission projects.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2016%2F05%2F16910.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2016%2F05%2FMicrosoftTeams-image.jpg&w=1920&q=90"]', 'RF Module', 34);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000012', '433MHz RSI Wireless Transmitter Receiver Kit', 'RSI-433MHZ-KIT', 12500, 'Complete RF transmitter and receiver solution for 433MHz frequency. Supports data transmission up to 3KHz from CMOS/TTL sources. Low current consumption (11mA typical). Easy integration with microcontrollers. Transmission range up to 50m. Ideal for RF-based applications and remote controls.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2018%2F02%2F58609-1-1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2018%2F02%2F58609-2-1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2018%2F02%2F58609-3-1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2018%2F02%2F58609-4.jpg&w=1920&q=90"]', 'RF Module', 28);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000013', 'RXB6 433MHz Superheterodyne Receiver Module', 'RXB6-433MHZ-RX', 15000, 'High-performance superheterodyne wireless receiver module. Receiver sensitivity -98dB, excellent selectivity and spurious radiation suppression. Temperature range -40°C to 85°C. Works with multiple receivers without interference. CE/FCC compliant. Perfect for reliable wireless reception.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F05%2F410158.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F05%2F9.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F05%2FRXB6-433Mhz-Superheterodyne-Wireless-Receiver-Module-4.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F05%2F4101582.jpg&w=1920&q=90"]', 'RF Module', 19);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000014', '315MHz RF Transmitter Receiver Wireless Link Kit', 'RF-315MHZ-LINK', 10000, '315MHz RF wireless link kit for Arduino and microcontroller projects. 4-channel operation, transmitting frequency 315MHz. Transmitter operating current 10mA at 12V, radiated power 10mW. Transmission distance 3-5 meters. Complete kit for wireless remote control applications.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2017%2F09%2FSKU-43118.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2017%2F09%2FSKU-43118-new.png&w=1920&q=90"]', 'RF Module', 0);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000015', '2.4GHz NRF24L01 Wireless Transceiver Module', 'NRF24L01-2.4G', 22500, '2.4GHz wireless transceiver module with integrated antenna. Operating voltage 1.9V-3.6V, ultra-low power consumption. Multi-frequency channel support, auto-retransmit and auto-acknowledge. SPI interface for easy MCU integration. Range up to 100m in open space. Ideal for wireless sensor networks.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F03%2Famit-10.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F03%2F0.2-37.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F03%2Famit-11.jpg&w=1920&q=90"]', 'RF Module', 41);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000016', 'XBee S2C Zigbee Module 2mW Wire Antenna', 'XBEE-S2C-WIRE', 287500, 'XBee 2mW Wire Antenna S2C featuring EM357 transceiver for improved performance. Point to multipoint connectivity, interoperable with ZigBee devices. Lower current draw, more RAM and Flash. 2mm pin spacing. Indoor range up to 60m, outdoor up to 1200m. Ideal for energy and control applications.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2014%2F12%2FSKU-2829.png&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2014%2F12%2FSKU-2829-new.png&w=1920&q=90"]', 'Zigbee Module', 5);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000017', 'XBee 3 Module PCB Antenna Zigbee BLE', 'XBEE3-PCB-ANT', 362500, 'XBee Series 3 module supporting 802.15.4, ZigBee and BLE protocols. Communication over UART or SPI. Indoor range 200ft, outdoor 4000ft. Built-in microcontroller programmable with MicroPython. HCS08 CPU at 50.33MHz, 15 digital I/O pins, 4x 10-bit ADC. PCB antenna included.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2F553.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2FXBee-3-Module-PCB-Antenna1.jpg&w=1920&q=90"]', 'Zigbee Module', 7);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000018', 'XBee 3 Pro Module RP-SMA Antenna', 'XBEE3-PRO-RPSMA', 487500, 'Professional-grade XBee 3 Pro module with RP-SMA antenna connector. Extended range and higher output power. Multi-protocol support including Zigbee, 802.15.4, and BLE. Programmable with MicroPython. Enhanced security features. Perfect for industrial automation and large-scale mesh networks.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2F83-2.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2F533.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F12%2F534.jpg&w=1920&q=90"]', 'Zigbee Module', 4);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000019', 'XBee USB Adapter Board for Configuration', 'XBEE-USB-ADAPTER', 137500, 'USB adapter for XBee module configuration and programming. FT232RL microprocessor, Mini-B USB interface. 3.3V and 5V power supply support. All XBee pins broken out to 2.54mm headers. Reset button included. Compatible with XCTU software for easy XBee configuration. Essential for XBee development.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2021%2F12%2F24-4.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2021%2F11%2F58196857-bc9d-43f5-bf3a-9b20cb308f40.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2021%2F11%2F1549032c-b747-46f0-890e-3e3923c822a1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2021%2F11%2Fb96d0975-f9e0-444a-84fd-4bcd0b588fe2-1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2021%2F11%2Fa1090fd2-0520-4782-8a48-f9cfc79a264a.jpg&w=1920&q=90"]', 'Development Tool', 14);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000020', 'Digi XBee3 Zigbee 3.0 Module', 'DIGI-XBEE3-ZB30', 325000, 'Digi XBee3 Zigbee 3.0 certified module with Silicon Labs EM357 SoC. RF data rate 250Kbps, serial up to 1Mbps. Transmit power up to 8dBm boost mode. Receiver sensitivity -102dBm. Support for mesh networking. Low power consumption. Ideal for smart energy and home automation applications.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2024%2F12%2F29-7.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2024%2F11%2F18.1.jpg&w=1920&q=90"]', 'Zigbee Module', 11);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000021', 'ESP32-CAM WiFi Bluetooth Camera Module OV2640', 'ESP32-CAM-OV2640', 84375, 'ESP32 development board with 2MP OV2640 camera module. WiFi 802.11 b/g/n and Bluetooth 4.2 LE. 32Mbit SPI flash, 4MBit PSRAM. MicroSD card slot up to 4GB. LED flashlight. UART, SPI, I2C, PWM interfaces. JPEG/BMP/grayscale image formats. Perfect for face recognition and IoT camera projects.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F06%2F526.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F06%2F456154-1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F06%2F456154-3-.jpg&w=1920&q=90"]', 'Camera Module', 22);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000022', 'OV7670 VGA Camera Module 0.3MP Arduino Compatible', 'OV7670-VGA-CAM', 62500, 'VGA camera module based on OV7670 CMOS image sensor. Resolution 640x480 (VGA), 30fps framerate. YUV/RGB output formats, automatic exposure control, gain control, white balance. F1.8/6mm lens included. Serial Camera Control Bus interface. Perfect for Arduino camera projects and machine vision.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2021%2F07%2F18.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2021%2F07%2FSKU-1031125.png&w=1920&q=90"]', 'Camera Module', 16);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000023', 'Arducam OV7670 Mini CCM Compact Camera Module', 'ARDUCAM-OV7670', 75000, 'Mini Compact Camera Module with OV7670 sensor and 24-pin Goldfinger interface. High quality stock lens, 30fps at VGA resolution. Programmable image processing including exposure, gamma, white balance, color saturation, hue control. DVP interface. Ideal for embedded vision applications.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F05%2F42.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F05%2F30W-Pixel-OV7670-Camera-Module-with-High-Quality-Connector-6.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F05%2F7670-Pinouts-and-Drawings.png&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F05%2F30W-Pixel-OV7670-Camera-Module-with-High-Quality-Connector-4.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F05%2F30W-Pixel-OV7670-Camera-Module-with-High-Quality-Connector-3.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F05%2F30W-Pixel-OV7670-Camera-Module-with-High-Quality-Connector-7.jpg&w=1920&q=90"]', 'Camera Module', 8);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000024', 'OV2640 2MP Camera Module for ESP32 Replacement', 'OV2640-2MP-MODULE', 47500, 'Standalone 2MP OV2640 camera module for ESP32-CAM replacement or upgrades. UXGA 1600x1200 resolution support. JPEG compression, automatic exposure and white balance. Low voltage CMOS operation. FPC ribbon cable connector. Compatible with ESP32-CAM and Arduino shields. Perfect for IoT imaging projects.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F09%2F11111111.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F08%2Fimgi_8_0.3MP-OV2640-Camera-Module-with-High-Quality-SCCB-Connector-4.jpg&w=1920&q=90"]', 'Camera Module', 31);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000025', 'ESP32-CAM-MB Programmer USB to Serial Adapter', 'ESP32-CAM-PROG', 31250, 'USB to serial programmer adapter specifically designed for ESP32-CAM module. CH340G USB driver chip. Auto-reset and boot mode selection. Micro USB interface for easy connection. Eliminates need for external FTDI programmer. Simply plug ESP32-CAM on top and program via USB. Essential ESP32-CAM accessory.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2023%2F09%2F14-6.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2023%2F09%2F1738329-2.jpg&w=1920&q=90"]', 'Development Tool', 0);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000026', 'AC1200 Dual Band WiFi USB Adapter 5GHz', 'AC1200-USB-WIFI', 62500, '1200Mbps dual-band wireless USB adapter. 5GHz (867Mbps) and 2.4GHz (300Mbps) bands. USB 3.0 for faster data transfer. High-gain external antennas for extended range. Supports Windows, Mac, Linux. WPA/WPA2 encryption. Ideal for HD streaming, gaming, and large file transfers.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F02%2FR213258-1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F02%2FR213258-2.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F02%2FR213258.jpg&w=1920&q=90"]', 'Network Adapter', 27);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000027', 'RTL8188 Mini USB WiFi Dongle 300Mbps', 'RTL8188-WIFI-MINI', 18750, 'Compact USB 2.0 WiFi adapter with RTL8188 chipset. 300Mbps Wireless-N speed, 5x faster than 802.11b/g. Supports 64/128-bit WEP, WPA/WPA2 encryption. Compatible with Windows, Mac, Linux, Raspberry Pi. QSS button for easy setup. CCA technology for stable connections. Perfect for older PC upgrades.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2022%2F08%2F684.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F01%2FRTL8188-Mini-USB-wireless-Network-Card-150Mbps-Wifi-Dongle-1-1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2019%2F01%2FRTL8188-Mini-USB-wireless-Network-Card-150Mbps-Wifi-Dongle-7.jpg&w=1920&q=90"]', 'Network Adapter', 45);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000028', 'WiFi 6 AX1800 Dual Band USB 3.0 Adapter', 'WIFI6-AX1800-USB', 87500, 'Next-generation WiFi 6 (802.11ax) USB adapter. Combined 1800Mbps speed (1201Mbps on 5GHz + 574Mbps on 2.4GHz). USB 3.0 interface, MU-MIMO technology. WPA3 security, beamforming support. Heat sink for stable performance. Future-proof your connectivity with WiFi 6. Ideal for gaming and 4K streaming.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F12%2F17.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F11%2F0.2-8.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F11%2F0.3-11.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F11%2F0.7-7.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F11%2F0.8-5.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F11%2F0.5-8.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2025%2F11%2F0.6-10.jpg&w=1920&q=90"]', 'Network Adapter', 13);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000029', 'AC600 Dual Band USB WiFi Adapter with Antenna', 'AC600-DUAL-USB', 37500, '600Mbps dual-band wireless adapter. 433Mbps on 5GHz, 150Mbps on 2.4GHz. External 5dBi antenna for better signal reception. USB 2.0 plug and play. Supports monitor mode and packet injection. Compatible with Kali Linux. WPS setup. Ideal for wireless penetration testing and general use.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2024%2F12%2F0.1.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2024%2F12%2F0.3.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2024%2F12%2F0.2.jpg&w=1920&q=90"]', 'Network Adapter', 36);
INSERT INTO products (product_id, name, code, price_cents, description, media_urls_json, type, stock) VALUES (X'AA000000000040008000000000000030', 'USB to Ethernet RJ45 LAN Network Adapter', 'USB-ETH-RJ45', 25000, 'USB 3.0 to Gigabit Ethernet adapter. 10/100/1000Mbps network speeds. Plug and play, no driver needed for most systems. Compact and portable design. Compatible with Windows, Mac, Linux, Chrome OS. Perfect for laptops without Ethernet port, stable wired connection, troubleshooting network issues.', '["https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fproduct%2F2424756%2FdtZITrwjOA84MHRFzsBio9At5PffXfKMebLhfreV.webp&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2024%2F12%2F0.34.jpg&w=1920&q=90","https://robu.in/_next/image/?url=https%3A%2F%2Frobu-prod-media.s3.ap-south-1.amazonaws.com%2Fuploads%2F2024%2F12%2F0.35.jpg&w=1920&q=90"]', 'Network Adapter', 52);
